package pzvrphysicality;

import java.util.*;import java.util.function.BooleanSupplier;

/** A bounded transaction over frame-owned numeric translations. Native orientations and all source models stay intact. */
public final class HeldContactPalette {
 private record Value(float[] target,int index,float before,float after){}
 public static final class Plan {
  private final Thread owner=Thread.currentThread();private final List<Value> values=new ArrayList<>();private boolean committed;
  public void add(float[] target,int index,double delta){if(committed||target==null||index<0||index>=target.length||!Double.isFinite(delta)||!Float.isFinite(target[index]))throw new IllegalArgumentException("Held frame edit");float after=(float)(target[index]+delta);if(!Float.isFinite(after))throw new IllegalArgumentException("Held edit overflow");for(var prior:values)if(prior.target==target&&prior.index==index){if(Math.abs(prior.after-after)>.00001)throw new IllegalArgumentException("Aliased incompatible held palette");return;}if(values.size()>=4096)throw new IllegalArgumentException("Held edit budget");values.add(new Value(target,index,target[index],after));}
  public int size(){return values.size();}
  public boolean commit(BooleanSupplier current){if(committed||Thread.currentThread()!=owner)throw new IllegalStateException("Held frame commit lifetime");if(!current.getAsBoolean())return false;for(var value:values)if(Float.floatToIntBits(value.target[value.index])!=Float.floatToIntBits(value.before))return false;for(var value:values)value.target[value.index]=value.after;boolean valid;try{valid=current.getAsBoolean();}catch(RuntimeException|LinkageError error){restore();throw error;}if(!valid){restore();return false;}committed=true;return true;}
  private void restore(){for(var value:values)value.target[value.index]=value.before;}
 }
 /** Convert a world XY/height correction into native render XYZ without changing native camera math. */
 public static double[] render(float[] world,double units,double maximum){if(world==null||world.length!=3||!Double.isFinite(units)||units<.25||units>4||!Double.isFinite(maximum)||maximum<.01||maximum>.08)throw new IllegalArgumentException("Held visual bound");double length=0;for(float value:world){if(!Float.isFinite(value))throw new IllegalArgumentException("Held correction finite");length+=value*value;}length=Math.sqrt(length);double factor=length>maximum*units?maximum*units/length:1;return new double[]{-world[0]*factor,world[2]*factor,-world[1]*factor};}
 public static double[] local(double[] render,float[] placement){if(render==null||render.length!=3||placement==null||placement.length!=16)throw new IllegalArgumentException("Held placement extent");for(float value:placement)if(!Float.isFinite(value))throw new IllegalArgumentException("Held placement finite");double a=placement[0],b=placement[4],c=placement[8],d=placement[1],e=placement[5],f=placement[9],g=placement[2],h=placement[6],i=placement[10];double det=a*(e*i-f*h)-b*(d*i-f*g)+c*(d*h-e*g);double product=Math.sqrt(a*a+d*d+g*g)*Math.sqrt(b*b+e*e+h*h)*Math.sqrt(c*c+f*f+i*i);if(product<1e-18||Math.abs(det)<product*.0001||Math.abs(placement[3])+Math.abs(placement[7])+Math.abs(placement[11])+Math.abs(placement[15]-1)>.0001)throw new IllegalArgumentException("Held affine placement");double x=render[0],y=render[1],z=render[2];return new double[]{((e*i-f*h)*x+(c*h-b*i)*y+(b*f-c*e)*z)/det,((f*g-d*i)*x+(a*i-c*g)*y+(c*d-a*f)*z)/det,((d*h-e*g)*x+(b*g-a*h)*y+(a*e-b*d)*z)/det};}
 public static boolean[] subtree(List<Integer> parents,int root,int socket){if(parents==null||parents.isEmpty()||parents.size()>256||root<0||root>=parents.size()||socket>=parents.size())throw new IllegalArgumentException("Held skeleton extent");boolean[] result=new boolean[parents.size()];for(int bone=0;bone<parents.size();bone++){int at=bone,steps=0;while(at>=0){if(at>=parents.size()||++steps>parents.size())throw new IllegalArgumentException("Held skeleton cycle/index");if(at==root||at==socket)result[bone]=true;Integer parent=parents.get(at);if(parent==null||parent==at)throw new IllegalArgumentException("Held skeleton parent");at=parent;}}if(socket>=0)result[socket]=true;return result;}
 public static void palette(Plan plan,float[] values,int base,boolean[] bones,double[] local){if(values==null||base<0||bones==null||local==null||local.length!=3||(long)(base+bones.length)*12>values.length)throw new IllegalArgumentException("Held palette extent");for(int bone=0;bone<bones.length;bone++)if(bones[bone])for(int axis=0;axis<3;axis++)plan.add(values,(base+bone)*12+axis*4+3,local[axis]);}
 public static void item(Plan plan,float[] values,int row,double[] render){if(values==null||row<0||(long)(row+1)*68>values.length||render==null||render.length!=3)throw new IllegalArgumentException("Held item row extent");for(int axis=0;axis<3;axis++)plan.add(values,row*68+12+axis,render[axis]);}
 private HeldContactPalette(){}
}
